{
  "root_causes": [
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name AS pod, count(*) AS n, round(avg(value),3) AS avg_v, max(value) AS max_v FROM abnormal_metrics WHERE attr_k8s_pod_name = 'profile-798c5d9c47-klz99' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY ALL",
          "claim": "The profile pod is never ready during the incident (ready avg 0) and its restart count climbs to 6."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, count(*) AS profile_spans FROM abnormal_traces WHERE service_name = 'profile' UNION ALL SELECT 'normal', count(*) FROM normal_traces WHERE service_name = 'profile'",
          "claim": "The profile service emits no spans during the incident, against about 2,300 spans in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT count(*) AS failed_calls, round(avg(duration)/1e6,3) AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'profile.Profile/GetProfiles' AND attr_span_kind = 'Client'",
          "claim": "Frontend's GetProfiles calls to profile all fail within about 0.01 ms, consistent with a refused connection to a down pod."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'frontend' AND level = 'ERROR' GROUP BY ALL",
          "claim": "Frontend logs 1627 ERROR entries, all reading 'Get profiles failed'."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "profile",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT f.span_name, f.attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces f WHERE f.service_name = 'frontend' AND f.attr_span_kind = 'Server' AND f.span_name IN ('HTTP /hotels','HTTP /recommendations') GROUP BY ALL ORDER BY 1,2",
          "claim": "User-facing /hotels and /recommendations requests return HTTP 500 at frontend, 724 and 407 times, matching the failed profile calls."
        }
      ]
    }
  ]
}
